 "\\omega=3,\\ r=5", [("expand((-2-4*I)*(8+4*I))/80", "-I/2", "quotient"), ("Abs(4*I-3)", "5", "C on circle"), ("Abs(-2-3)", "5", "A"), ("Abs(4*I)**2-Abs(-2)*Abs(8)", "0", "relation")],
